import json, glob, os, re, sys, collections

D = sys.argv[1]
mode = sys.argv[2]  # diff | leak


def load(p):
    with open(p) as f:
        return json.load(f)


def resolve(doc):
    props, sets, lists = doc['props'], doc['propSets'], doc['nameLists']
    out = {}
    for name, c in doc['components'].items():
        r = {}
        r['props'] = {}
        for pid in c.get('props', []):
            p = props.get(pid)
            r['props'][p['name'] if p else pid] = p
        for i, inh in enumerate(c.get('inheritance', [])):
            key = 'inh:%s' % inh.get('typeName')
            m = sets.get(inh.get('members'), {}) if isinstance(inh.get('members'), str) else inh.get('members')
            r[key + ':members'] = {k: props.get(v, v) if isinstance(v, str) else v for k, v in (m or {}).items()}
            om = inh.get('omitted')
            r[key + ':omitted'] = lists.get(om, om) if isinstance(om, str) else om
        rest = {k: v for k, v in c.items() if k not in ('props', 'inheritance')}
        r['rest'] = rest
        out[name] = r
    return out


def fallbacks(doc):
    return [d for d in doc['diagnostics'] if d.get('code') == 'SEMANTIC_BACKEND' and re.search(r'timed out|shut down|budget|heap|panicked|did not answer|could not start|stopped', d.get('message',''), re.I)]


def diag_key(d):
    return (d.get('code'), d.get('file'), d.get('message'))


def short(v):
    s = json.dumps(v, sort_keys=True)
    return s if len(s) < 160 else s[:157] + '...'


if mode == 'diff':
    groups = collections.defaultdict(list)
    for p in sorted(glob.glob(D + '/*.json')):
        n = os.path.basename(p)[:-5]
        corpus, cfg, i = n.split('.')
        groups[(corpus, cfg)].append((int(i), p))
    for (corpus, cfg), runs in sorted(groups.items()):
        runs.sort()
        docs = []
        for i, p in runs:
            doc = load(p)
            rc = open(p[:-5] + '.rc').read().strip()
            docs.append((i, doc, resolve(doc), len(fallbacks(doc)), rc, open(p[:-5] + '.meta').read().strip()))
        nfb = sum(1 for d in docs if d[3])
        # group runs by full-content equality
        sigs = collections.OrderedDict()
        for i, doc, res, fb, rc, meta in docs:
            s = json.dumps(doc, sort_keys=True)
            sigs.setdefault(s, []).append(i)
        print('== %s %s: runs=%d distinct=%d degraded_runs=%d rc=%s' % (
            corpus, cfg, len(docs), len(sigs), nfb, sorted({d[4] for d in docs})))
        print('   loads/secs:', '; '.join('%d:%s' % (d[0], d[5].replace('load=', '').replace(' secs=', ' s=')) for d in docs[:2]), '...')
        if len(sigs) == 1:
            continue
        base = docs[0]
        for i, doc, res, fb, rc, meta in docs[1:]:
            if json.dumps(doc, sort_keys=True) == json.dumps(base[1], sort_keys=True):
                continue
            changed = []
            for name in sorted(set(res) | set(base[2])):
                a, b = base[2].get(name), res.get(name)
                if a == b:
                    continue
                if a is None or b is None:
                    changed.append((name, 'present only in %s' % ('run %d' % base[0] if b is None else 'run %d' % i)))
                    continue
                pd = []
                for sec in sorted(set(a) | set(b)):
                    if a.get(sec) == b.get(sec):
                        continue
                    sa, sb = a.get(sec), b.get(sec)
                    if isinstance(sa, dict) and isinstance(sb, dict):
                        for k in sorted(set(sa) | set(sb)):
                            if sa.get(k) != sb.get(k):
                                pd.append('%s.%s' % (sec, k))
                    else:
                        pd.append(sec)
                changed.append((name, ','.join(pd[:6]) + (' +%d' % (len(pd) - 6) if len(pd) > 6 else '')))
            fa, fb2 = {diag_key(d) for d in base[1]['diagnostics']}, {diag_key(d) for d in doc['diagnostics']}
            print('  run %d vs run %d: fallbackdiags %d vs %d; components differing=%d; diag-only-in-base=%d only-in-this=%d' % (
                i, base[0], base[3], fb, len(changed), len(fa - fb2), len(fb2 - fa)))
            for name, what in changed[:6]:
                print('     %s: %s' % (name, what))
            if changed:
                name = changed[0][0]
                a, b = base[2].get(name), res.get(name)
                if a and b:
                    for sec in sorted(set(a) | set(b)):
                        sa, sb = a.get(sec), b.get(sec)
                        if sa != sb and isinstance(sa, dict) and isinstance(sb, dict):
                            for k in sorted(set(sa) | set(sb)):
                                if sa.get(k) != sb.get(k):
                                    print('       eg %s.%s: base=%s | this=%s' % (sec, k, short(sa.get(k)), short(sb.get(k))))
                                    break
                            break
            for d in fallbacks(doc)[:2]:
                print('     fallback diag:', d['message'][:200])
elif mode == 'leak':
    pat = re.compile(r'__#|__@|#\d+|@\d+|@#|\banonymous\b|\(Anonymous class\)|__type|__object|__class', re.I)
    skip = {'description', 'message', 'help', 'file', 'filePath', 'fileName', 'declarations', 'tags', 'defaultValue', 'text'}
    counts = collections.defaultdict(collections.Counter)
    examples = collections.defaultdict(dict)

    def walk(v, key, corpus_cfg, comp):
        if isinstance(v, dict):
            for k, x in v.items():
                # property names appear as dict keys in propSets
                if isinstance(k, str) and pat.search(k):
                    counts[corpus_cfg]['dictkey'] += 1
                    examples[corpus_cfg].setdefault('dictkey:' + pat.search(k).group(0), k)
                walk(x, k, corpus_cfg, comp)
        elif isinstance(v, list):
            for x in v:
                walk(x, key, corpus_cfg, comp)
        elif isinstance(v, str) and key not in skip:
            m = pat.search(v)
            if m:
                counts[corpus_cfg][key] += 1
                examples[corpus_cfg].setdefault('%s:%s' % (key, m.group(0)), v[:100])

    for p in sorted(glob.glob(D + '/*.1.json')):
        n = os.path.basename(p)[:-7]
        corpus, cfg = n.split('.')
        doc = load(p)
        walk({k: v for k, v in doc.items() if k != 'diagnostics'}, None, (corpus, cfg), None)
        counts[(corpus, cfg)]['_total'] += 0
    for k in sorted(counts):
        print(k, dict(counts[k]))
        for e, v in list(examples[k].items())[:8]:
            print('    ', e, '=>', v)
